//         13  ldr r6, [r1, #8]  z     ldr r4, [r2]
//         14  add r2, r0, #0x14       ldr r7, [r0, #4]   y
//         16  asr r1, r5, #6          ldr r6, [r1, #8]   z
//         17  ldr r4, [r2]            asr r1, r5, #6
